    const missing=await fetch(`${origin}/agentone/commands/${missingId}`,{headers:{cookie}});assert.equal(missing.status,404);const missingText=await missing.text();assert.match(missingText,/command_run_not_found/);assert.doesNotMatch(missingText,/database_error|internal-secret/);
