test('chat routing redacts provider failures, rejects empty streams and cancels disconnected clients',async()=>{
  const providerPort=await freePort(),proxyPort=await freePort(),requests=[];let logs='',providerCancelObserved=false;
  const provider=http.createServer(async(req,res)=>{
    let body='';for await(const chunk of req)body+=chunk;const input=JSON.parse(body);requests.push(input);
    if(input.stream&&input.input==='provider auth secret 401'){res.writeHead(401,{'content-type':'application/json'});return res.end('{"error":{"message":"sensitive-auth-provider-detail"}}');}
    if(input.stream&&input.input==='provider auth secret 403'){res.writeHead(403,{'content-type':'application/json'});return res.end('{"error":{"message":"sensitive-forbidden-provider-detail"}}');}
    if(input.stream&&input.input==='provider missing secret 404'){res.writeHead(404,{'content-type':'application/json'});return res.end('{"error":{"message":"sensitive-missing-provider-detail"}}');}
    if(input.stream&&input.input==='provider stream failure'){res.writeHead(200,{'content-type':'text/event-stream'});return res.end('data: '+JSON.stringify({type:'response.failed',response:{error:{message:'sensitive-stream-provider-detail'}}})+'\n\ndata: [DONE]\n\n');}
    if(input.stream&&input.input==='empty provider stream'){res.writeHead(200,{'content-type':'text/event-stream'});return res.end('data: [DONE]\n\n');}
    if(input.stream&&input.input==='truncated provider stream'){res.writeHead(200,{'content-type':'text/event-stream'});return res.end('data: '+JSON.stringify({type:'response.output_text.delta',delta:'partial-only'})+'\n\n');}
    if(input.stream&&input.input==='cancel provider stream'){
      res.writeHead(200,{'content-type':'text/event-stream'});res.write('data: '+JSON.stringify({type:'response.output_text.delta',delta:'first-cancel-delta'})+'\n\n');
      const keepAlive=setInterval(()=>res.write(': keepalive\n\n'),25);keepAlive.unref?.();res.once('close',()=>{clearInterval(keepAlive);providerCancelObserved=true;});return;
    }
    if(input.stream){res.writeHead(200,{'content-type':'text/event-stream'});res.write('data: '+JSON.stringify({type:'response.output_text.delta',delta:'trace-ok'})+'\n\n');return res.end('data: [DONE]\n\n');}
    res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify({output_text:'trace-ok'}));
  });
  await new Promise(resolve=>provider.listen(providerPort,'127.0.0.1',resolve));
  const origin=`http://127.0.0.1:${proxyPort}`,child=spawn(process.execPath,['server/basic-proxy.mjs'],{cwd:process.cwd(),env:{...process.env,HOST:'127.0.0.1',PORT:String(proxyPort),UPSTREAM_URL:`http://127.0.0.1:${providerPort}`,BASIC_AUTH_USER:'trace-user',BASIC_AUTH_PASSWORD:'trace-password-with-enough-length',AUTHENTICATED_USER:'trace@local',AGENTONE_DISPLAY_NAME:'Günni',AGENTONE_RELEASE:'trace-test',OPENAI_API_KEY:'test-key-never-logged',OPENAI_BASE_URL:`http://127.0.0.1:${providerPort}`,ACCESS_SESSION_SECRET:'trace-session-secret-with-enough-length',PUBLIC_ORIGIN:origin},stdio:['ignore','pipe','pipe']});child.stdout.on('data',chunk=>logs+=chunk);child.stderr.on('data',chunk=>logs+=chunk);
  try{
    await waitFor(`${origin}/proxy-health`);const login=await fetch(`${origin}/login`,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded',origin},body:'username=trace-user&password=trace-password-with-enough-length',redirect:'manual'}),cookie=login.headers.get('set-cookie').split(';')[0],streamRequest=(text,model='gpt-6.1-sol',signal)=>fetch(`${origin}/agentone/voice/chat/stream`,{method:'POST',headers:{cookie,origin,'content-type':'application/json'},body:JSON.stringify({text,language:'de-DE',model}),signal});
    const streamed=await streamRequest('private prompt must never be logged');assert.equal(streamed.status,200);const events=(await streamed.text()).trim().split('\n').map(line=>JSON.parse(line));assert.equal(events[0].type,'started');assert.equal(events[0].model,'gpt-6.1-sol');assert.equal(events[1].delta,'trace-ok');assert.equal(events.at(-1).type,'done');
    for(const [text,code] of [['provider auth secret 401','VOICE_CHAT_PROVIDER_AUTH_FAILED'],['provider auth secret 403','VOICE_CHAT_PROVIDER_AUTH_FAILED'],['provider missing secret 404','VOICE_CHAT_PROVIDER_CONFIGURATION_ERROR']]){const response=await streamRequest(text),payload=await response.json();assert.equal(response.status,503);assert.equal(payload.error,code);assert.equal(payload.retryable,false);assert.doesNotMatch(JSON.stringify(payload),/sensitive-|provider-detail/i);}
    const providerFailure=await streamRequest('provider stream failure'),providerFailureEvents=(await providerFailure.text()).trim().split('\n').map(line=>JSON.parse(line));assert.equal(providerFailure.status,200);assert.equal(providerFailureEvents[0].type,'started');assert.equal(providerFailureEvents.at(-1).type,'error');assert.equal(providerFailureEvents.at(-1).code,'VOICE_CHAT_STREAM_FAILED');assert.equal(providerFailureEvents.some(event=>event.type==='done'),false);assert.doesNotMatch(JSON.stringify(providerFailureEvents),/sensitive-stream-provider-detail/);
    const empty=await streamRequest('empty provider stream'),emptyEvents=(await empty.text()).trim().split('\n').map(line=>JSON.parse(line));assert.equal(empty.status,200);assert.equal(emptyEvents.at(-1).type,'error');assert.equal(emptyEvents.at(-1).code,'VOICE_CHAT_EMPTY');assert.equal(emptyEvents.some(event=>event.type==='done'),false);
    const truncated=await streamRequest('truncated provider stream'),truncatedEvents=(await truncated.text()).trim().split('\n').map(line=>JSON.parse(line));assert.equal(truncated.status,200);assert.equal(truncatedEvents.at(-1).type,'error');assert.equal(truncatedEvents.at(-1).code,'VOICE_CHAT_STREAM_INCOMPLETE');assert.equal(truncatedEvents.some(event=>event.type==='done'),false);
    const fallback=await fetch(`${origin}/agentone/voice/chat`,{method:'POST',headers:{cookie,origin,'content-type':'application/json'},body:JSON.stringify({text:'another private prompt',language:'en-US',model:'not-allowed'})});assert.equal(fallback.status,200);assert.equal((await fallback.json()).model,'gpt-6-luna');
    const logOffset=logs.length,cancelController=new AbortController(),cancelResponse=await streamRequest('cancel provider stream','gpt-6.1-terra',cancelController.signal),cancelReader=cancelResponse.body.getReader();await cancelReader.read();cancelController.abort();for(let attempt=0;attempt<40&&!providerCancelObserved;attempt+=1)await new Promise(resolve=>setTimeout(resolve,25));assert.equal(providerCancelObserved,true);await new Promise(resolve=>setTimeout(resolve,30));const cancelLogs=logs.slice(logOffset);assert.match(cancelLogs,/voice\.chat\.failed/);assert.match(cancelLogs,/VOICE_CHAT_CLIENT_ABORTED/);assert.doesNotMatch(cancelLogs,/voice\.chat\.completed/);
    assert.equal(requests[0].model,'gpt-6.1-sol');assert.equal(requests.at(-2).model,'gpt-6-luna');assert.match(logs,/voice\.chat\.completed/);assert.match(logs,/voice\.chat\.failed/);assert.match(logs,/VOICE_CHAT_STREAM_FAILED/);assert.match(logs,/VOICE_CHAT_STREAM_INCOMPLETE/);assert.match(logs,/VOICE_CHAT_EMPTY/);assert.match(logs,/"latencyMs":\d+/);assert.doesNotMatch(logs,/private prompt|provider auth secret|provider missing secret|provider stream failure|truncated provider stream|empty provider stream|cancel provider stream|sensitive-|test-key-never-logged/);
  }finally{child.kill();await new Promise(resolve=>provider.close(resolve));}
});

test('voice transcription negotiates browser formats, uses plural language hints and redacts provider failures',async()=>{
  const providerPort=await freePort(),proxyPort=await freePort();let providerCalls=0,receivedMultipart='',receivedType='',logs='';
  const provider=http.createServer(async(req,res)=>{
    if(req.url!=='/v1/audio/transcriptions'){res.writeHead(404);return res.end();}
    providerCalls++;receivedType=String(req.headers['content-type']||'');const chunks=[];for await(const chunk of req)chunks.push(chunk);receivedMultipart=Buffer.concat(chunks).toString('latin1');
    if(providerCalls===1){res.writeHead(200,{'content-type':'application/json'});return res.end('{"text":"Hallo aus dem Mikrofon","languages":[{"code":"de"}]}');}
    const failureStatus=[400,401,403,404][providerCalls-2]||500;res.writeHead(failureStatus,{'content-type':'application/json'});res.end(`{"error":{"message":"sensitive-provider-detail-${failureStatus}-must-not-leak","code":"provider_failure"}}`);
  });
  await new Promise(resolve=>provider.listen(providerPort,'127.0.0.1',resolve));
  const origin=`http://127.0.0.1:${proxyPort}`,child=spawn(process.execPath,['server/basic-proxy.mjs'],{cwd:process.cwd(),env:{...process.env,HOST:'127.0.0.1',PORT:String(proxyPort),UPSTREAM_URL:`http://127.0.0.1:${providerPort}`,BASIC_AUTH_USER:'voice-user',BASIC_AUTH_PASSWORD:'voice-password-with-enough-length',AUTHENTICATED_USER:'voice@local',AGENTONE_DISPLAY_NAME:'Günni',OPENAI_API_KEY:'voice-key-must-never-be-logged',OPENAI_BASE_URL:`http://127.0.0.1:${providerPort}`,ACCESS_SESSION_SECRET:'voice-session-secret-with-enough-length',PUBLIC_ORIGIN:origin},stdio:['ignore','pipe','pipe']});child.stdout.on('data',chunk=>logs+=chunk);child.stderr.on('data',chunk=>logs+=chunk);
  try{
    await waitFor(`${origin}/proxy-health`);const login=await fetch(`${origin}/login`,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded',origin},body:'username=voice-user&password=voice-password-with-enough-length',redirect:'manual'}),cookie=login.headers.get('set-cookie').split(';')[0];
    const statusResponse=await fetch(`${origin}/agentone/voice/status`,{headers:{cookie}});assert.equal(statusResponse.status,200);const status=await statusResponse.json();assert.equal(status.status,'LIVE');assert.equal(status.model,'gpt-transcribe');assert.equal(status.languageField,'languages[]');assert.equal(status.secretsExposed,false);assert.equal(JSON.stringify(status).includes('voice-key'),false);
    const unsupported=await fetch(`${origin}/agentone/voice/transcribe`,{method:'POST',headers:{cookie,origin,'content-type':'application/octet-stream','x-agentone-language':'de-DE'},body:Buffer.alloc(1024,1)});assert.equal(unsupported.status,415);assert.equal((await unsupported.json()).error,'VOICE_FORMAT_UNSUPPORTED');assert.equal(providerCalls,0);
    const tooShort=await fetch(`${origin}/agentone/voice/transcribe`,{method:'POST',headers:{cookie,origin,'content-type':'audio/webm','x-agentone-language':'de-DE','x-agentone-audio-duration-ms':'50'},body:Buffer.alloc(16,1)});assert.equal(tooShort.status,400);const tooShortBody=await tooShort.json();assert.equal(tooShortBody.error,'VOICE_AUDIO_TOO_SHORT');assert.match(tooShortBody.message,/zu kurz/i);assert.equal(providerCalls,0);
    const success=await fetch(`${origin}/agentone/voice/transcribe`,{method:'POST',headers:{cookie,origin,'content-type':'audio/mp4;codecs=mp4a.40.2','x-agentone-language':'de-DE','x-agentone-audio-duration-ms':'1200'},body:Buffer.alloc(2048,1)});assert.equal(success.status,200);const successBody=await success.json();assert.equal(successBody.text,'Hallo aus dem Mikrofon');assert.equal(successBody.diagnostics.mimeType,'audio/mp4');assert.match(receivedType,/multipart\/form-data; boundary=/);assert.match(receivedMultipart,/name="model"\r\n\r\ngpt-transcribe/);assert.match(receivedMultipart,/name="languages\[\]"\r\n\r\nde/);assert.doesNotMatch(receivedMultipart,/name="language"/);assert.match(receivedMultipart,/filename="voice\.mp4"/);assert.match(receivedMultipart,/Content-Type: audio\/mp4/i);
    const transcribe=()=>fetch(`${origin}/agentone/voice/transcribe`,{method:'POST',headers:{cookie,origin,'content-type':'audio/ogg','x-agentone-language':'de-DE','x-agentone-audio-duration-ms':'1200'},body:Buffer.alloc(1024,2)});
    const rejected=await transcribe();assert.equal(rejected.status,422);const rejectedBody=await rejected.json();assert.equal(rejectedBody.error,'VOICE_AUDIO_REJECTED');assert.match(rejectedBody.message,/konnte nicht verarbeitet/i);assert.doesNotMatch(JSON.stringify(rejectedBody),/HTTP 400|sensitive-provider-detail|voice-key/i);
    for(const [providerStatus,errorCode] of [[401,'VOICE_PROVIDER_AUTH_FAILED'],[403,'VOICE_PROVIDER_AUTH_FAILED'],[404,'VOICE_PROVIDER_CONFIGURATION_ERROR']]){const response=await transcribe(),payload=await response.json();assert.equal(response.status,503);assert.equal(payload.error,errorCode);assert.equal(payload.retryable,false);assert.doesNotMatch(JSON.stringify(payload),new RegExp(`HTTP ${providerStatus}|sensitive-provider-detail|voice-key`,'i'));}
    await new Promise(resolve=>setTimeout(resolve,30));assert.match(logs,/voice\.transcription\.completed/);assert.match(logs,/voice\.transcription\.failed/);for(const upstreamStatus of [400,401,403,404])assert.match(logs,new RegExp(`"upstreamStatus":${upstreamStatus}`));assert.doesNotMatch(logs,/sensitive-provider-detail|voice-key-must-never-be-logged|Hallo aus dem Mikrofon/);
  }finally{child.kill();await new Promise(resolve=>provider.close(resolve));}
});
